    JSON.stringify(
      {
        request: {
          operation: request.operation,
          sql: request.sql,
          id: request.id,
          method: request.method,
          path: request.path,
          key: request.key,
        },
        environment: operation.result?.environment,
        result: printable,
      },
      null,
      2,
    ),
  );
}
